package com.pratik.imagetap;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;import android.view.*;import android.widget.FrameLayout;import java.util.*;
/** Decorative only: no touch interception. Animates only while this surface is visible. */
final class NerveSurface extends FrameLayout {
 private final Paint p=new Paint(3);private final List<Path> routes=new ArrayList<>();private final List<PathMeasure> lengths=new ArrayList<>();private final float[] point=new float[2];private long touchAt=-10000;private final boolean live;
 NerveSurface(Context c,boolean live){super(c);this.live=live;setWillNotDraw(false);setBackgroundColor(Ui.BG);}
 @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){routes.clear();lengths.clear();for(int i=0;i<14;i++){float x=w*(i+.5f)/14,dx=(i%2==0?1:-1)*w*.07f,offset=(i%3)*.025f;Path path=new Path();path.moveTo(x,h);path.lineTo(x,h*(.88f-offset));path.lineTo(x+dx,h*(.82f-offset));path.lineTo(x+dx,h*(.70f-offset));path.lineTo(x+dx*.3f,h*(.64f-offset));path.lineTo(x+dx*.3f,h*(.48f-offset));path.lineTo(x+dx*1.15f,h*(.42f-offset));path.lineTo(x+dx*1.15f,h*(.29f-offset));path.lineTo(x+dx*.4f,h*(.23f-offset));routes.add(path);lengths.add(new PathMeasure(path,false));}}
 @Override public boolean dispatchTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){touchAt=SystemClock.uptimeMillis();invalidate();}return super.dispatchTouchEvent(e);}
 @Override protected void onDraw(Canvas c){super.onDraw(c);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Ui.dp(getContext(),.7f));p.setColor(0xff15283c);for(Path route:routes)c.drawPath(route,p);if(live){boolean motion=Ui.motion(getContext());long now=SystemClock.uptimeMillis();float phase=motion?(now%4200)/4200f:0;float touch=(now-touchAt)/1400f;if(motion&&touch>=0&&touch<1)phase=touch;for(int i=0;i<lengths.size();i++){float local=(phase+i*.035f)%1;PathMeasure m=lengths.get(i);if(local>.75f)continue;m.getPosTan(m.getLength()*local/.75f,point,null);p.setStyle(Paint.Style.FILL);p.setColor(Ui.GREEN);p.setAlpha(motion?45:12);c.drawCircle(point[0],point[1],Ui.dp(getContext(),6),p);p.setAlpha(motion?130:35);c.drawCircle(point[0],point[1],Ui.dp(getContext(),1.6f),p);}p.setAlpha(255);if(motion&&isShown()&&getWindowVisibility()==VISIBLE)postInvalidateDelayed(50);}}
}
